  async quickConfigureAttachmentFolder(button) {
    const vault = this.plugin.app.vault;
    const setting = this.app.setting;
    const openFileSettings = () => {
      setting?.open?.();
      setting?.openTabById?.("files");
    };
    if (!vault.setConfig) {
      openFileSettings();
      new import_obsidian28.Notice("\u8BF7\u5728\u201C\u6587\u4EF6\u4E0E\u94FE\u63A5\u201D\u4E2D\u5C06\u65B0\u9644\u4EF6\u7684\u9ED8\u8BA4\u4F4D\u7F6E\u8BBE\u4E3A\u6307\u5B9A\u6587\u4EF6\u5939\uFF1AAttachment");
      return;
    }
    button.disabled = true;
    try {
      const folder = vault.getAbstractFileByPath("Attachment");
      if (folder && !(folder instanceof import_obsidian28.TFolder)) {
        new import_obsidian28.Notice("Attachment \u5DF2\u88AB\u6587\u4EF6\u5360\u7528\uFF0C\u8BF7\u5728\u201C\u6587\u4EF6\u4E0E\u94FE\u63A5\u201D\u4E2D\u624B\u52A8\u9009\u62E9\u5176\u4ED6\u6587\u4EF6\u5939");
        openFileSettings();
        return;
      }
      if (!folder) await vault.createFolder("Attachment");
      await vault.setConfig("attachmentFolderPath", "Attachment");
      const updated = readObsidianAttachmentLocation(this.plugin);
      if (updated.mode !== "fixed-folder" || updated.folder !== "Attachment") {
        throw new Error("Obsidian \u672A\u5E94\u7528\u9644\u4EF6\u76EE\u5F55\u8BBE\u7F6E");
      }
      this.renderSettings();
      openFileSettings();
      new import_obsidian28.Notice("\u4EE5\u540E\u65B0\u589E\u7684\u9644\u4EF6\u5C06\u5B58\u653E\u5728 Attachment\uFF1B\u73B0\u6709\u9644\u4EF6\u4E0D\u4F1A\u81EA\u52A8\u79FB\u52A8");
    } catch (error) {
      openFileSettings();
      new import_obsidian28.Notice(`\u5FEB\u901F\u914D\u7F6E\u5931\u8D25\uFF1A${error instanceof Error ? error.message : String(error)}`);
    } finally {
      button.disabled = false;
    }
  }
