    const exportButton = row.createEl("button", { cls: "simple-rule-del", attr: { title: "\u5BFC\u51FA\u89C4\u5219", "aria-label": "\u5BFC\u51FA\u89C4\u5219" } });
    (0, import_obsidian28.setIcon)(exportButton, "download");
